;\n  font-weight: 700;\n  letter-spacing: 0.96px;\n  margin-bottom: 12px;\n  text-transform: uppercase;\n}\n.game-item .game-tagline {\n  color: #aaaaaa;\n  font-size: 13px;\n  line-height: 22px;\n  margin-bottom: 15px;\n  -webkit-box-flex: 1;\n  -webkit-flex-grow: 1;\n  -moz-flex-grow: 1;\n  -ms-flex-positive: 1;\n  flex-grow: 1;\n}\n.game-item:hover::before {\n  bottom: 8px;\n  left: 8px;\n  right: 8px;\n  top: 8px;\n}\n.game-item:hover .game-hex {\n  background-color: #fa6862;\n}\n.game-item:hover .game-hex::before {\n  border-bottom-color: #fa6862;\n}\n.game-item:hover .game-hex::after {\n  border-top-color: #fa6862;\n}\n\n.game-hex {\n  background-color: #293342;\n  display: block;\n  height: 32.33px;\n  margin: 16.16px auto 24px;\n  position: relative;\n  width: 56px;\n  -webkit-transition: all 0.3s ease 0s;\n  -moz-transition: all 0.3s ease 0s;\n  -o-transition: all 0.3s ease 0s;\n  transition: all 0.3s ease 0s;\n}\n.game-hex::before, .game-hex::after {\n  border-left: 28px solid transparent;\n  border-right: 28px solid transparent;\n  content: \"\";\n  left: 0;\n  position: absolute;\n  width: 0;\n  -webkit-transition: all 0.3s ease 0s;\n  -moz-transition: all 0.3s ease 0s;\n  -o-transition: all 0.3s ease 0s;\n  transition: all 0.3s ease 0s;\n}\n.game-hex::before {\n  border-bottom: 16.16px solid #293342;\n  bottom: 100%;\n}\n.game-hex::after {\n  border-top: 16.16px solid #293342;\n  top: 100%;\n}\n.game-hex i {\n  color: #fff;\n  font-size: 24px;\n  left: 50%;\n  position: absolute;\n  top: 50%;\n  z-index: 1;\n  -webkit-transform: translate(-50%, -50%);\n  -moz-transform: translate(-50%, -50%);\n  -ms-transform: translate(-50%, -50%);\n  -o-transform: translate(-50%, -50%);\n  transform: translate(-50%, -50%);\n}\n\n.game-meta {\n  line-height: 20px;\n  min-height: 22px;\n}\n\n.game-badge {\n  border-radius: 2px;\n  color: #cfd6e4;\n  display: inline-block;\n  font-size: 10px;\n  letter-spacing: 1px;\n  line-height: 20px;\n  margin: 0 1px;\n  padding: 0 8