d {\n  -webkit-transform: translateX(0px);\n  -moz-transform: translateX(0px);\n  -ms-transform: translateX(0px);\n  -o-transform: translateX(0px);\n  transform: translateX(0px);\n}\n\n.switcher-head {\n  color: #333;\n  font-size: 18px;\n  font-weight: 600;\n  height: 46px;\n  line-height: 46px;\n  position: relative;\n}\n\n.switcher-head span {\n  border-bottom: 2px solid #eeeeee;\n  display: block;\n  margin: 0 20px;\n}\n\n.switcher-trigger {\n  background-color: #fff;\n  border: 1px solid #ddd;\n  border-right: 0;\n  cursor: pointer;\n  font-size: 20px;\n  height: 48px;\n  left: -48px;\n  line-height: 46px;\n  position: absolute;\n  text-align: center;\n  top: -1px;\n  width: 48px;\n}\n\n.switcher-body {\n  background-color: #fff;\n  height: -webkit-calc(100% - 50px);\n  height: calc(100% - 50px);\n  left: 0;\n  padding: 20px;\n  position: fixed;\n  right: 0;\n  top: 47px;\n  outline: none;\n}\n\n.switcher-body h4 {\n  font-size: 16px;\n  margin-bottom: 10px;\n}\n\n.switcher-body select {\n  border: 1px solid #e5e5e5;\n  height: 40px;\n  margin-bottom: 20px;\n  width: 100%;\n  -webklit--appearance: none;\n  -moz-appearance: none;\n  appearance: none;\n}\n\n.color-options {\n  margin-bottom: 10px;\n  padding: 0;\n}\n\n.color-options li {\n  display: inline-block;\n  background-color: #e6ae03;\n  height: 30px;\n  margin-bottom: 10px;\n  margin-right: 6px;\n  text-indent: -9999em;\n  width: 30px;\n  cursor: pointer;\n}\n\n.color-options li.c0 {\n  background-color: #fa6862;\n}\n\n.color-options li.c1 {\n  background-color: #02b7ce;\n}\n\n.color-options li.c2 {\n  background-color: #86a438;\n}\n\n.color-options li.c3 {\n  background-color: #f3a36d;\n}\n\n.pattern-options li {\n  font-family: \"Roboto\", sans-serif;\n  border: 1px solid #cccccc;\n  cursor: pointer;\n  float: left;\n  height: 40px;\n  margin: 0 10px 10px 0;\n  text-transform: capitalize;\n  width: 50px;\n}\n\n.pattern-options li:last-child {\n  border: 0 none;\n  height: auto;\n  padding-top: 8px;\n  width: auto;\n}\n\n.pattern-options li img {\n  width: 100%;\n  height: 100%;\n}\n\n/*------------------------------------------------\n\tResponsive Media Queries\n-------------------------------------------------*/\n/*============================================================\n\tMacbook pro 13 inch\n==============================================================*/\n/*============================================================\n\tFor Small Desktop / tablet landscape\n==============================================================*/\n@media (min-width: 980px) and (max-width: 1150px) {\n  .author-image-large img {\n    height: -webkit-calc(80vh - 4px);\n    height: -moz-calc(80vh - 4px);\n    height: calc(80vh - 4px);\n  }\n}\n/*============================================================\n\tTablet (Portrait) Design for a width of 768px\n==============================================================*/\n@media (min-width: 768px) and (max-width: 979px) {\n  body {\n    overflow-x: hidden;\n  }\n  .page-title h2 {\n    font-size: 40px;\n  }\n  .page-title .title-bg {\n    font-size: 100px;\n  }\n  .author-image-large {\n    position: static;\n    margin-bottom: 50px;\n  }\n  .author-image-large img {\n    display: block;\n    height: auto;\n    margin: 0 auto;\n    width: 50%;\n  }\n  .about-author + p {\n    margin-bottom: 50px;\n  }\n  .service-hex {\n    width: 33.3333%;\n  }\n  .service-hex:hover {\n    z-index: 2;\n  }\n  .service-hex:hover svg {\n    -webkit-transform: scale(1.5);\n    -moz-transform: scale(1.5);\n    -ms-transform: scale(1.5);\n    -o-transform: scale(1.5);\n    transform: scale(1.5);\n  }\n  .service-hex:hover .content {\n    width: 105%;\n  }\n  .service-hex:nth-child(4), .service-hex:nth-child(5) {\n    -webkit-transform: translate(50%, -15%);\n    -moz-transform: translate(50%, -15%);\n    -ms-transform: translate(50%, -15%);\n    -o-transform: translate(50%, -15%);\n    transform: translate(50%, -15%);\n  }\n  .testimonials .item {\n    padding-top: 45px;\n  }\n  .testimonials .thumb {\n    margin-top: -45px;\n  }\n  .history-item .history-text {\n    padding-right: 15px;\n  }\n  .page-nav {\n    bottom: auto;\n  }\n  .page-nav .flex {\n    display: block;\n    text-align: center;\n  }\n  .page-nav .flex span {\n    display: block;\n    margin: 20px 0;\n  }\n}\n/*============================================================\n\tMobile (Portrait) Design for a width of 320px\n==============================================================*/\n@media only screen and (max-width: 767px) {\n  body {\n    overflow-x: hidden;\n  }\n  .pt-table {\n    height: auto;\n  }\n  .pt-table,\n  .pt-tablecell {\n    display: block;\n  }\n  .page-title {\n    margin-bottom: 45px;\n  }\n  .page-title h2 {\n    font-size: 35px;\n  }\n  .page-title .title-bg {\n    font-size: 50px;\n  }\n  .hexagon-item {\n    float: none;\n    margin: 0 auto 50px;\n  }\n  .hexagon-item:first-child {\n    margin-left: auto;\n  }\n  .page-home .hexagon-item:nth-child(n+5) {\n    -webkit-transform: rotate(30deg) translate(0px, 0px);\n    -moz-transform: rotate(30deg) translate(0px, 0px);\n    -ms-transform: rotate(30deg) translate(0px, 0px);\n    -o-transform: rotate(30deg) translate(0px, 0px);\n    transform: rotate(30deg) translate(0px, 0px);\n  }\n  .author-image-large {\n    position: static;\n    margin-bottom: 50px;\n  }\n  .author-image-large img {\n    display: block;\n    height: auto;\n    margin: 0 auto;\n    width: 50%;\n  }\n  .about-author {\n    display: block;\n  }\n  .about-author .author-thumb {\n    border: 0 none;\n    margin-bottom: 15px;\n    margin-right: 0;\n    padding: 0;\n  }\n  .about-author .author-desc b {\n    display: block;\n  }\n  .about-author + p {\n    margin-bottom: 50px;\n  }\n  .progress {\n    display: block;\n  }\n  .progress .skill-name {\n    border-right: 0;\n    margin: 0 15px;\n    min-width: auto;\n    text-align: left;\n  }\n  .progress .skill-lavel {\n    border-left: 0;\n    margin: 0 15px;\n    min-width: auto;\n    text-align: left;\n  }\n  .service-hex {\n    float: none;\n    margin: 0 auto 40px;\n    width: 60%;\n  }\n  .service-hex:last-child {\n    margin-bottom: 0;\n  }\n  .service-hex:hover svg {\n    -webkit-transform: scale(1.8);\n    -moz-transform: scale(1.8);\n    -ms-transform: scale(1.8);\n    -o-transform: scale(1.8);\n    transform: scale(1.8);\n  }\n  .service-hex:hover .content {\n    width: 120%;\n  }\n  .history-block {\n    margin-bottom: 30px;\n  }\n  .contact-form .input-field.name {\n    margin-right: 0;\n  }\n  .page-nav {\n    bottom: auto;\n  }\n  .page-nav .flex {\n    display: block;\n    text-align: center;\n  }\n  .page-nav .flex span {\n    display: block;\n    margin: 20px 0;\n  }\n}\n.dark {\n  background-color: #0c0f15;\n}\n.dark .page-home .overlay {\n  background-color: rgba(14, 17, 24, 0.97);\n}\n.dark .page-title h2 {\n  color: #ffffff;\n}\n.dark .page-title .title-bg {\n  color: rgba(70, 88, 124, 0.06);\n}\n.dark .section-title h3::before {\n  background-color: #fff;\n}\n.dark h1,\n.dark h2,\n.dark h3,\n.dark h4,\n.dark h5,\n.dark h6,\n.dark .about-author .author-desc p {\n  color: #fff;\n}\n.dark .switcher-body h4 {\n  color: #0c0f15;\n}\n.dark .service-hex .st0 {\n  fill: transparent;\n}\n.dark .service-hex:hover .st0 {\n  fill: #fff;\n}\n.dark .testimonials .text,\n.dark .btn-border {\n  border-color: #1e2530;\n}","//\r\n// Mixins\r\n//\r\n\r\n@import \"flex\";\r\n\r\n@mixin transition($transition) {\r\n   -webkit-transition: $transition;\r\n   -moz-transition: $transition;\r\n   -o-transition: $transition;\r\n   transition: $transition;\r\n}\r\n\r\n@mixin transform($transform) {\r\n   -webkit-transform: $transform;\r\n   -moz-transform: $transform;\r\n   -ms-transform: $transform;\r\n   -o-transform: $transform;\r\n   transform: $transform;\r\n}\r\n\r\n@mixin transform-origin($value) {\r\n   -webkit-transform-origin: $value;\r\n   -moz-transform-origin: $value;\r\n   -ms-transform-origin: $value;\r\n   -o-transform-origin: $value;\r\n   transform-origin: $value;\r\n}\r\n\r\n@mixin transition-delay($value) {\r\n   -webkit-transition-delay: $value;\r\n   -moz-transition-delay: $value;\r\n   -o-transition-delay: $value;\r\n   transition-delay: $value;\r\n}\r\n\r\n@mixin backface-visibility($value) {\r\n   -webkit-transform-origin: $value;\r\n   -moz-transform-origin: $value;\r\n   transform-origin: $value;\r\n}\r\n\r\n@mixin calc($property, $expression) {\r\n   #{$property}: -webkit-calc(#{$expression});\r\n   #{$property}: -moz-calc(#{$expression});\r\n   #{$property}: calc(#{$expression});\r\n}","// Flexbox Mixins\r\n// http://philipwalton.github.io/solved-by-flexbox/\r\n// https://github.com/philipwalton/solved-by-flexbox\r\n// \r\n// Copyright (c) 2013 Brian Franco\r\n//\r\n// Permission is hereby granted, free of charge, to any person obtaining a\r\n// copy of this software and associated documentation files (the\r\n// \"Software\"), to deal in the Software without restriction, including\r\n// without limitation the rights to use, copy, modify, merge, publish,\r\n// distribute, sublicense, and/or sell copies of the Software, and to\r\n// permit persons to whom the Software is furnished to do so, subject to\r\n// the following conditions:\r\n// The above copyright notice and this permission notice shall be included\r\n// in all copies or substantial portions of the Software.\r\n// THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS\r\n// OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF\r\n// MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT.\r\n// IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY\r\n// CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT,\r\n// TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\r\n// SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\r\n//\r\n// This is a set of mixins for those who want to mess around with flexbox\r\n// using the native support of current browsers. For full support table\r\n// check: http://caniuse.com/flexbox\r\n//\r\n// Basically this will use:\r\n//\r\n// * Fallback, old syntax (IE10, mobile webkit browsers - no wrapping)\r\n// * Final standards syntax (FF, Safari, Chrome, IE11, Opera)\r\n//\r\n// This was inspired by:\r\n// \r\n// * http://dev.opera.com/articles/view/advanced-cross-browser-flexbox/\r\n// \r\n// With help from:\r\n// \r\n// * http://w3.org/tr/css3-flexbox/\r\n// * http://the-echoplex.net/flexyboxes/\r\n// * http://msdn.microsoft.com/en-us/library/ie/hh772069(v=vs.85).aspx\r\n// * http://css-tricks.com/using-flexbox/\r\n// * http://dev.opera.com/articles/view/advanced-cross-browser-flexbox/\r\n// * https://developer.mozilla.org/en-us/docs/web/guide/css/flexible_boxes\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Containers\r\n//\r\n// The 'flex' value causes an element to generate a block-level flex\r\n// container box.\r\n//\r\n// The 'inline-flex' value causes an element to generate a inline-level\r\n// flex container box. \r\n//\r\n// display: flex | inline-flex\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-containers\r\n//\r\n// (Placeholder selectors for each type, for those who rather @extend)\r\n\r\n@mixin flexbox {\r\n\tdisplay: -webkit-box;\r\n\tdisplay: -webkit-flex;\r\n\tdisplay: -moz-flex;\r\n\tdisplay: -ms-flexbox;\r\n\tdisplay: flex;\r\n}\r\n\r\n%flexbox { @include flexbox; }\r\n\r\n//----------------------------------\r\n\r\n@mixin inline-flex {\r\n\tdisplay: -webkit-inline-box;\r\n\tdisplay: -webkit-inline-flex;\r\n\tdisplay: -moz-inline-flex;\r\n\tdisplay: -ms-inline-flexbox;\r\n\tdisplay: inline-flex;\r\n}\r\n\r\n%inline-flex { @include inline-flex; }\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Direction\r\n//\r\n// The 'flex-direction' property specifies how flex items are placed in\r\n// the flex container, by setting the direction of the flex container's\r\n// main axis. This determines the direction that flex items are laid out in. \r\n//\r\n// Values: row | row-reverse | column | column-reverse\r\n// Default: row\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-direction-property\r\n\r\n@mixin flex-direction($value: row) {\r\n\t@if $value == row-reverse {\r\n\t\t-webkit-box-direction: reverse;\r\n\t\t-webkit-box-orient: horizontal;\r\n\t} @else if $value == column {\r\n\t\t-webkit-box-direction: normal;\r\n\t\t-webkit-box-orient: vertical;\r\n\t} @else if $value == column-reverse {\r\n\t\t-webkit-box-direction: reverse;\r\n\t\t-webkit-box-orient: vertical;\r\n\t} @else {\r\n\t\t-webkit-box-direction: normal;\r\n\t\t-webkit-box-orient: horizontal;\r\n\t}\r\n\t-webkit-flex-direction: $value;\r\n\t-moz-flex-direction: $value;\r\n\t-ms-flex-direction: $value;\r\n\tflex-direction: $value;\r\n}\r\n\t// Shorter version:\r\n\t@mixin flex-dir($args...) { @include flex-direction($args...); }\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Wrap\r\n//\r\n// The 'flex-wrap' property controls whether the flex container is single-line\r\n// or multi-line, and the direction of the cross-axis, which determines\r\n// the direction new lines are stacked in. \r\n//\r\n// Values: nowrap | wrap | wrap-reverse\r\n// Default: nowrap\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-wrap-property\r\n\r\n@mixin flex-wrap($value: nowrap) {\r\n\t// No Webkit Box fallback.\r\n\t-webkit-flex-wrap: $value;\r\n\t-moz-flex-wrap: $value;\r\n\t@if $value == nowrap {\r\n\t\t-ms-flex-wrap: none;\r\n\t} @else { \r\n\t\t-ms-flex-wrap: $value; \r\n\t}\r\n\tflex-wrap: $value;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Flow (shorthand)\r\n//\r\n// The 'flex-flow' property is a shorthand for setting the 'flex-direction'\r\n// and 'flex-wrap' properties, which together define the flex container's\r\n// main and cross axes.\r\n//\r\n// Values: <flex-direction> | <flex-wrap> \r\n// Default: row nowrap\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-flow-property\r\n\r\n@mixin flex-flow($values: (row nowrap)) {\r\n\t// No Webkit Box fallback.\r\n\t-webkit-flex-flow: $values;\r\n\t-moz-flex-flow: $values;\r\n\t-ms-flex-flow: $values;\r\n\tflex-flow: $values;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Order\r\n//\r\n// The 'order' property controls the order in which flex items appear within\r\n// their flex container, by assigning them to ordinal groups.\r\n//\r\n// Default: 0\r\n//\r\n// http://w3.org/tr/css3-flexbox/#order-property\r\n\r\n@mixin order($int: 0) {\r\n\t-webkit-box-ordinal-group: $int + 1;\r\n\t-webkit-order: $int;\r\n\t-moz-order: $int;\r\n\t-ms-flex-order: $int;\r\n\torder: $int;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Grow\r\n//\r\n// The 'flex-grow' property sets the flex grow factor. Negative numbers\r\n// are invalid.\r\n//\r\n// Default: 0\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-grow-property\r\n\r\n@mixin flex-grow($int: 0) {\r\n\t-webkit-box-flex: $int;\r\n\t-webkit-flex-grow: $int;\r\n\t-moz-flex-grow: $int;\r\n\t-ms-flex-positive: $int;\r\n\tflex-grow: $int;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Shrink\r\n//\r\n// The 'flex-shrink' property sets the flex shrink factor. Negative numbers\r\n// are invalid.\r\n//\r\n// Default: 1\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-shrink-property\r\n\r\n@mixin flex-shrink($int: 1) {\r\n\t-webkit-flex-shrink: $int;\r\n\t-moz-flex-shrink: $int;\r\n\t-ms-flex-negative: $int;\r\n\tflex-shrink: $int;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Basis\r\n//\r\n// The 'flex-basis' property sets the flex basis. Negative lengths are invalid. \r\n//\r\n// Values: Like \"width\" \r\n// Default: auto\r\n//\r\n// http://www.w3.org/TR/css3-flexbox/#flex-basis-property\r\n\r\n@mixin flex-basis($value: auto) {\r\n\t-webkit-flex-basis: $value;\r\n\t-moz-flex-basis: $value;\r\n\t-ms-flex-preferred-size: $value;\r\n\tflex-basis: $value;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox \"Flex\" (shorthand)\r\n//\r\n// The 'flex' property specifies the components of a flexible length: the\r\n// flex grow factor and flex shrink factor, and the flex basis. When an\r\n// element is a flex item, 'flex' is consulted instead of the main size\r\n// property to determine the main size of the element. If an element is\r\n// not a flex item, 'flex' has no effect.\r\n//\r\n// Values: none | <flex-grow> <flex-shrink> || <flex-basis>\r\n// Default: See individual properties (1 1 0).\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-property\r\n\r\n@mixin flex($fg: 1, $fs: null, $fb: null) {\r\n    \r\n\t// Set a variable to be used by box-flex properties\r\n\t$fg-boxflex: $fg;\r\n\r\n\t// Box-Flex only supports a flex-grow value so let's grab the\r\n\t// first item in the list and just return that.\r\n\t@if type-of($fg) == 'list' {\r\n\t\t$fg-boxflex: nth($fg, 1);\r\n\t}\r\n\r\n\t-webkit-box-flex: $fg-boxflex;\r\n\t-webkit-flex: $fg $fs $fb;\r\n\t-moz-box-flex: $fg-boxflex;\r\n\t-moz-flex: $fg $fs $fb;\r\n\t-ms-flex: $fg $fs $fb;\r\n\tflex: $fg $fs $fb;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Justify Content\r\n//\r\n// The 'justify-content' property aligns flex items along the main axis\r\n// of the current line of the flex container. This is done after any flexible\r\n// lengths and any auto margins have been resolved. Typically it helps distribute\r\n// extra free space leftover when either all the flex items on a line are\r\n// inflexible, or are flexible but have reached their maximum size. It also\r\n// exerts some control over the alignment of items when they overflow the line.\r\n//\r\n// Note: 'space-*' values not supported in older syntaxes.\r\n//\r\n// Values: flex-start | flex-end | center | space-between | space-around\r\n// Default: flex-start\r\n//\r\n// http://w3.org/tr/css3-flexbox/#justify-content-property\r\n\r\n@mixin justify-content($value: flex-start) {\r\n\t@if $value == flex-start {\r\n\t\t-webkit-box-pack: start;\r\n\t\t-ms-flex-pack: start;\r\n\t} @else if $value == flex-end {\r\n\t\t-webkit-box-pack: end;\r\n\t\t-ms-flex-pack: end;\r\n\t} @else if $value == space-between {\r\n\t\t-webkit-box-pack: justify;\r\n\t\t-ms-flex-pack: justify;\r\n\t} @else if $value == space-around {\r\n\t\t-ms-flex-pack: distribute;\t\t\r\n\t} @else {\r\n\t\t-webkit-box-pack: $value;\r\n\t\t-ms-flex-pack: $value;\r\n\t}\r\n\t-webkit-justify-content: $value;\r\n\t-moz-justify-content: $value;\r\n\tjustify-content: $value;\r\n}\r\n\t// Shorter version:\r\n\t@mixin flex-just($args...) { @include justify-content($args...); }\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Align Items\r\n//\r\n// Flex items can be aligned in the cross axis of the current line of the\r\n// flex container, similar to 'justify-content' but in the perpendicular\r\n// direction. 'align-items' sets the default alignment for all of the flex\r\n// container's items, including anonymous flex items. 'align-self' allows\r\n// this default alignment to be overridden for individual flex items. (For\r\n// anonymous flex items, 'align-self' always matches the value of 'align-items'\r\n// on their associated flex container.) \r\n//\r\n// Values: flex-start | flex-end | center | baseline | stretch\r\n// Default: stretch\r\n//\r\n// http://w3.org/tr/css3-flexbox/#align-items-property\r\n\r\n@mixin align-items($value: stretch) {\r\n\t@if $value == flex-start {\r\n\t\t-webkit-box-align: start;\r\n\t\t-ms-flex-align: start;\r\n\t} @else if $value == flex-end {\r\n\t\t-webkit-box-align: end;\r\n\t\t-ms-flex-align: end;\r\n\t} @else {\r\n\t\t-webkit-box-align: $value;\r\n\t\t-ms-flex-align: $value;\r\n\t}\r\n\t-webkit-align-items: $value;\r\n\t-moz-align-items: $value;\r\n\talign-items: $value;\r\n}\r\n\r\n//----------------------------------\r\n\r\n// Flexbox Align Self\r\n//\r\n// Values: auto | flex-start | flex-end | center | baseline | stretch\r\n// Default: auto\r\n\r\n@mixin align-self($value: auto) {\r\n\t// No Webkit Box Fallback.\r\n\t-webkit-align-self: $value;\r\n\t-moz-align-self: $value;\r\n\t@if $value == flex-start {\r\n\t\t-ms-flex-item-align: start;\r\n\t} @else if $value == flex-end {\r\n\t\t-ms-flex-item-align: end;\r\n\t} @else {\r\n\t\t-ms-flex-item-align: $value;\r\n\t}\r\n\talign-self: $value;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Align Content\r\n//\r\n// The 'align-content' property aligns a flex container's lines within the\r\n// flex container when there is extra space in the cross-axis, similar to\r\n// how 'justify-content' aligns individual items within the main-axis. Note,\r\n// this property has no effect when the flexbox has only a single line.\r\n//\r\n// Values: flex-start | flex-end | center | space-between | space-around | stretch\r\n// Default: stretch\r\n//\r\n// http://w3.org/tr/css3-flexbox/#align-content-property\r\n\r\n@mixin align-content($value: stretch) {\r\n\t// No Webkit Box Fallback.\r\n\t-webkit-align-content: $value;\r\n\t-moz-align-content: $value;\r\n\t@if $value == flex-start {\r\n\t\t-ms-flex-line-pack: start;\r\n\t} @else if $value == flex-end {\r\n\t\t-ms-flex-line-pack: end;\r\n\t} @else {\r\n\t\t-ms-flex-line-pack: $value;\r\n\t}\r\n\talign-content: $value;\r\n}","@import \"variables\";\r\n@import \"mixins\";\r\n@import \"base\";\r\n\r\n.preloader {\r\n  bottom: 0;\r\n  left: 0;\r\n  position: fixed;\r\n  right: 0;\r\n  top: 0;\r\n  z-index: 1000;\r\n  @include flexbox();\r\n  &.active.hidden {\r\n    display: none;\r\n  }\r\n}\r\n\r\n.loading-mask {\r\n  background-color: $primary-color;\r\n  height: 100%;\r\n  left: 0;\r\n  position: absolute;\r\n  top: 0;\r\n  width: 20%;\r\n  @include transition(all 0.6s cubic-bezier(0.61, 0, 0.6, 1) 0s);\r\n\r\n  &:nth-child(2) {\r\n    left: 20%;\r\n    @include transition-delay(0.1s);\r\n  }\r\n  &:nth-child(3) {\r\n    left: 40%;\r\n    @include transition-delay(0.2s);\r\n  }\r\n  &:nth-child(4) {\r\n    left: 60%;\r\n    @include transition-delay(0.3s);\r\n  }\r\n  &:nth-child(5) {\r\n    left: 80%;\r\n    @include transition-delay(0.4s);\r\n  }\r\n}\r\n\r\n.preloader.active {\r\n  &.done {\r\n    z-index: 0;\r\n  }\r\n  .loading-mask {\r\n    width: 0;\r\n  }\r\n}\r\n\r\n/*------------------------------------------------\r\n\tStart Styling\r\n-------------------------------------------------*/\r\n.site-wrapper {\r\n  border-top: 4px solid $primary-color;\r\n}\r\n\r\n.page-close {\r\n  font-size: 30px;\r\n  position: absolute;\r\n  right: 30px;\r\n  top: 30px;\r\n  z-index: 100;\r\n}\r\n\r\n.page-title {\r\n  margin-bottom: 75px;\r\n  img {\r\n    margin-bottom: 20px;\r\n  }\r\n  h2 {\r\n    font-size: 68px;\r\n    margin-bottom: 25px;\r\n    position: relative;\r\n    z-index: 0;\r\n    font-weight: 900;\r\n    text-transform: uppercase;\r\n  }\r\n  p {\r\n    font-size: 16px;\r\n  }\r\n  .title-bg {\r\n    color: rgba($light-dark, 0.07);\r\n    font-size: 158px;\r\n    left: 50%;\r\n    letter-spacing: 10px;\r\n    line-height: 0.7;\r\n    position: absolute;\r\n    top: 50%;\r\n    z-index: -1;\r\n    @include transform(translate(-50%, -50%));\r\n  }\r\n}\r\n\r\n.section-title {\r\n  margin-bottom: 20px;\r\n  overflow: hidden;\r\n  h3 {\r\n    display: inline-block;\r\n    position: relative;\r\n    &::before,\r\n    &::after {\r\n      content: \"\";\r\n      height: 2px;\r\n      position: absolute;\r\n      bottom: 8px;\r\n      @include calc(left, \"100% + 14px\");\r\n    }\r\n    &::before {\r\n      background-color: $light-dark;\r\n      width: 96px;\r\n      bottom: 14px;\r\n    }\r\n    &::after {\r\n      background-color: $primary-color;\r\n      width: 73px;\r\n    }\r\n  }\r\n  &.light {\r\n    h3 {\r\n      color: $light;\r\n      &::before {\r\n        background-color: $light;\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n.page-nav {\r\n  bottom: 40px;\r\n  left: 0;\r\n  position: absolute;\r\n  right: 0;\r\n  span {\r\n    font-family: $open-sans;\r\n    font-size: 14px;\r\n    font-weight: 500;\r\n    line-height: 1.3;\r\n    text-transform: uppercase;\r\n  }\r\n}\r\n\r\n//\r\n// Home\r\n//\r\n@import \"blocks/home\";\r\n@import \"blocks/welcome\";\r\n@import \"blocks/about\";\r\n@import \"blocks/games\";\r\n\r\n// about\r\n.progress {\r\n  background-color: $light-dark;\r\n  border-radius: 2px;\r\n  height: auto;\r\n  min-height: 45px;\r\n  @include align-items(center);\r\n  @include flexbox();\r\n  & > div {\r\n    color: $light;\r\n    font-family: $open-sans;\r\n    font-size: 12px;\r\n    letter-spacing: 1px;\r\n  }\r\n  .skill-name {\r\n    border-right: 2px solid #2e333a;\r\n    min-width: 160px;\r\n    text-align: center;\r\n    text-transform: uppercase;\r\n  }\r\n  .skill-bar {\r\n    background-color: #07080b;\r\n    border-radius: 15px;\r\n    margin: 0 15px;\r\n    @include flex-grow(1);\r\n  }\r\n  .bar {\r\n    background-color: $primary-color;\r\n    border-radius: 10px;\r\n    height: 8px;\r\n    width: 0;\r\n  }\r\n  .skill-lavel {\r\n    border-left: 2px solid #2e333a;\r\n    min-width: 70px;\r\n    text-align: center;\r\n    @include align-items(flex-end);\r\n    @include transition(all 0.3s ease 0s);\r\n  }\r\n}\r\n\r\n// Works\r\n\r\n.filter {\r\n  margin-bottom: 30px;\r\n  a {\r\n    border-bottom: 2px solid transparent;\r\n  }\r\n  .active {\r\n    color: $primary-color;\r\n    border-bottom-color: $primary-color;\r\n  }\r\n}\r\n\r\n.works-item {\r\n  font-family: $open-sans;\r\n  margin-bottom: 30px;\r\n  position: relative;\r\n\r\n  img {\r\n    width: 100%;\r\n  }\r\n\r\n  .overlay {\r\n    background-color: rgba(#1e2530, 0.96);\r\n    position: absolute;\r\n    left: 0;\r\n    top: 0;\r\n    height: 100%;\r\n    width: 100%;\r\n    @include transition(all 0.3s ease 0s);\r\n    @include transform(scale(0));\r\n    &::before {\r\n      border: 1px solid $light;\r\n      bottom: 15px;\r\n      content: \"\";\r\n      left: 15px;\r\n      position: absolute;\r\n      right: 15px;\r\n      top: 15px;\r\n    }\r\n  }\r\n\r\n  .works-inner {\r\n    left: 50%;\r\n    position: absolute;\r\n    text-align: center;\r\n    top: 50%;\r\n    white-space: nowrap;\r\n    @include transition(all 0.3s ease 0s);\r\n    @include transform(translate3d(0px, 0px, 0px) scale(0));\r\n  }\r\n\r\n  h4 {\r\n    color: $primary-color;\r\n    font-weight: 700;\r\n    text-transform: uppercase;\r\n  }\r\n\r\n  p {\r\n    color: $light;\r\n    font-size: 12px;\r\n    font-weight: 400;\r\n  }\r\n\r\n  &:hover {\r\n    .overlay {\r\n      @include transform(scale(1));\r\n    }\r\n    .works-inner {\r\n      @include transform(translate(-50%, -50%) scale(1));\r\n    }\r\n  }\r\n}\r\n\r\n// history/ resume\r\n\r\n.history-block {\r\n  background-color: $light-dark;\r\n  position: relative;\r\n  .section-title {\r\n    background-color: $light-dark;\r\n    border-bottom: 1px solid #293342;\r\n    left: 0;\r\n    margin-bottom: 0;\r\n    padding: 15px 34px 14px;\r\n    position: absolute;\r\n    right: 0;\r\n    top: 0;\r\n    z-index: 1;\r\n  }\r\n}\r\n\r\n.nicescroll-rails {\r\n  z-index: 2;\r\n}\r\n\r\n.history-scroller {\r\n  padding-top: 82px;\r\n  max-height: 377px;\r\n}\r\n\r\n.history-item {\r\n  display: table;\r\n  font-family: $open-sans;\r\n  padding-left: 32px;\r\n  margin-bottom: 20px;\r\n  width: 100%;\r\n  & > * {\r\n    display: table-cell;\r\n    vertical-align: middle;\r\n  }\r\n  .history-icon {\r\n    padding-right: 25px;\r\n    position: relative;\r\n    width: 66px;\r\n    i {\r\n      font-size: 18px;\r\n      position: absolute;\r\n      top: 50%;\r\n      @include calc(left, \"50% - 12.5px\");\r\n      transform: translate(-50%, -50%);\r\n    }\r\n  }\r\n  h5 {\r\n    color: $light;\r\n    font-size: 16px;\r\n    font-weight: 600;\r\n    letter-spacing: 0.96px;\r\n    text-transform: uppercase;\r\n  }\r\n  span {\r\n    color: #aaaaaa;\r\n    font-size: 12px;\r\n  }\r\n}\r\n\r\n.history-hex {\r\n  display: block;\r\n  position: relative;\r\n  width: 66px;\r\n  height: 38.11px;\r\n  background-color: #293342;\r\n  margin: 19.05px 0;\r\n  &::before,\r\n  &::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    width: 0;\r\n    border-left: 33px solid transparent;\r\n    border-right: 33px solid transparent;\r\n  }\r\n  &::before {\r\n    bottom: 100%;\r\n    border-bottom: 19.05px solid #293342;\r\n  }\r\n  &::after {\r\n    top: 100%;\r\n    width: 0;\r\n    border-top: 19.05px solid #293342;\r\n  }\r\n}\r\n\r\n// Service hex\r\n//--------------------------------------\r\n.service-hex {\r\n  float: left;\r\n  position: relative;\r\n  width: 20%;\r\n  z-index: 1;\r\n  svg {\r\n    @include transform(scale(1.08));\r\n    @include transition(all 0.4s ease 0s);\r\n  }\r\n  .st0 {\r\n    stroke: $light-dark;\r\n    fill: #fff;\r\n  }\r\n  .st1 {\r\n    fill: $light-dark;\r\n  }\r\n  .content {\r\n    color: $light;\r\n    left: 50%;\r\n    position: absolute;\r\n    text-align: center;\r\n    top: 50%;\r\n    width: 100%;\r\n    @include transform(translate(-50%, -50%));\r\n  }\r\n  .icon {\r\n    font-size: 30px;\r\n    margin-bottom: 9px;\r\n  }\r\n  h4 {\r\n    color: $light;\r\n    font-size: 16px;\r\n    margin-bottom: 20px;\r\n  }\r\n  p {\r\n    font-size: 14px;\r\n    height: 0;\r\n    line-height: 24px;\r\n    overflow: hidden;\r\n    @include transition(all 0.4s ease 0s);\r\n  }\r\n  &:hover {\r\n    z-index: 2;\r\n    svg {\r\n      @include transform(scale(1.5));\r\n    }\r\n    .st1 {\r\n      fill: $primary-color;\r\n    }\r\n    .content {\r\n      width: 135%;\r\n    }\r\n    p {\r\n      height: 72px;\r\n    }\r\n  }\r\n}\r\n\r\n// testimonials\r\n//--------------------------------------\r\n\r\n.testimonials {\r\n  .item {\r\n    padding-top: 33px;\r\n  }\r\n  .thumb {\r\n    float: left;\r\n    margin-top: -20px;\r\n    img {\r\n      width: auto;\r\n    }\r\n    @media only screen and (max-width: 991px) {\r\n      float: none;\r\n      margin-top: 0;\r\n      margin: auto;\r\n    }\r\n  }\r\n  .text {\r\n    border: 1px solid #cecece;\r\n    font-size: 14px;\r\n    font-style: italic;\r\n    line-height: 24px;\r\n    margin-left: 50px;\r\n    padding: 27px 30px 29px 142px;\r\n\r\n    @media only screen and (max-width: 991px) {\r\n      padding: 29px 30px 29px 30px;\r\n      margin-bottom: 20px;\r\n      text-align: center;\r\n    }\r\n  }\r\n  figcaption {\r\n    font-family: $open-sans;\r\n    font-size: 16px;\r\n    font-weight: 700;\r\n    padding-top: 15px;\r\n    text-align: center;\r\n  }\r\n  h4 {\r\n    font-family: $open-sans;\r\n    font-weight: 700;\r\n  }\r\n  span {\r\n    font-size: 12px;\r\n  }\r\n  .slick-slide {\r\n    margin: 0 15px;\r\n    &:focus {\r\n      outline: 0;\r\n    }\r\n    &:nth-child(2n) {\r\n      .thumb {\r\n        float: right;\r\n\r\n        @media only screen and (max-width: 991px) {\r\n          float: none;\r\n        }\r\n      }\r\n      .text {\r\n        margin-left: 0;\r\n        margin-right: 50px;\r\n        padding: 27px 142px 29px 30px;\r\n\r\n        @media only screen and (max-width: 991px) {\r\n          padding: 29px 30px 29px 30px;\r\n          margin-right: 0;\r\n        }\r\n      }\r\n    }\r\n  }\r\n  .slick-dots {\r\n    text-align: center;\r\n    button {\r\n      border: 2px solid $light-dark;\r\n      border-radius: 15px;\r\n      display: inline-block;\r\n      height: 11px;\r\n      margin: 0 4px;\r\n      width: 11px;\r\n      @include transition(all 0.3s ease 0s);\r\n\r\n      &:before {\r\n        display: none;\r\n      }\r\n    }\r\n    .slick-active button {\r\n      border-color: $primary-color;\r\n    }\r\n  }\r\n}\r\n\r\n.tm-hex {\r\n  position: relative;\r\n  width: 170px;\r\n  height: 98.15px;\r\n  margin: 49.07px 0;\r\n  background-size: auto 182.4427px;\r\n  background-position: center;\r\n  border-left: solid 6px $title-color;\r\n  border-right: solid 6px $title-color;\r\n\r\n  @media only screen and (max-width: 991px) {\r\n    margin: 49.07px auto;\r\n  }\r\n  &::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    top: 3.4641px;\r\n    left: 0;\r\n    width: 158px;\r\n    height: 91.2213px;\r\n    z-index: 2;\r\n    background: inherit;\r\n  }\r\n  .hexTop,\r\n  .hexBottom {\r\n    position: absolute;\r\n    z-index: 1;\r\n    width: 120.21px;\r\n    height: 120.21px;\r\n    overflow: hidden;\r\n    background: inherit;\r\n    left: 18.9px;\r\n    @include transform(scaleY(0.5774) rotate(-45deg));\r\n    &::before,\r\n    &::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      width: 158px;\r\n      height: 91.22134253196087px;\r\n      background: inherit;\r\n      @include transform-origin(0 0);\r\n      @include transform(rotate(45deg) scaleY(1.7321) translateY(-45.6107px));\r\n    }\r\n  }\r\n\r\n  .hexTop {\r\n    top: -60.1041px;\r\n    border-top: solid 8.4853px $title-color;\r\n    border-right: solid 8.4853px $title-color;\r\n    &::after {\r\n      background-position: center top;\r\n    }\r\n  }\r\n\r\n  .hexBottom {\r\n    bottom: -60.1041px;\r\n    border-bottom: solid 8.4853px $title-color;\r\n    border-left: solid 8.4853px $title-color;\r\n    &::after {\r\n      background-position: center bottom;\r\n    }\r\n  }\r\n}\r\n\r\n// contact\r\n\r\n.contact-block {\r\n  margin-bottom: 30px;\r\n  &:last-child {\r\n    margin-bottom: 0;\r\n  }\r\n  .media-left {\r\n    font-size: 40px;\r\n    max-width: 50px;\r\n    min-width: 50px;\r\n    padding-right: 0;\r\n    text-align: center;\r\n  }\r\n  .media-body {\r\n    padding-left: 30px;\r\n  }\r\n  h4 {\r\n    font-size: 18px;\r\n    text-transform: uppercase;\r\n    font-weight: 600;\r\n  }\r\n  p {\r\n    font-weight: 400;\r\n    font-size: 15px;\r\n  }\r\n}\r\n\r\n.contact-social {\r\n  list-style: outside none none;\r\n  margin: 0;\r\n  padding: 0;\r\n  li {\r\n    display: inline-block;\r\n    position: relative;\r\n    width: 43px;\r\n    a {\r\n      color: $light;\r\n      display: block;\r\n      font-size: 14px;\r\n      height: 50px;\r\n      left: 50%;\r\n      line-height: 50px;\r\n      position: absolute;\r\n      text-align: center;\r\n      top: 50%;\r\n      width: 43px;\r\n      @include transform(translate(-50%, -50%));\r\n    }\r\n    &:hover {\r\n      span {\r\n        background-color: $primary-color;\r\n        &::before {\r\n          border-bottom-color: $primary-color;\r\n        }\r\n        &::after {\r\n          border-top-color: $primary-color;\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n.contact-social-hex {\r\n  display: block;\r\n  position: relative;\r\n  width: 43px;\r\n  height: 24.83px;\r\n  background-color: #1e2530;\r\n  margin: 12.41px 0;\r\n  @include transition(all 0.3s ease 0s);\r\n  &::before,\r\n  &::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    width: 0;\r\n    border-left: 21.5px solid transparent;\r\n    border-right: 21.5px solid transparent;\r\n    @include transition(all 0.3s ease 0s);\r\n  }\r\n  &::before {\r\n    bottom: 100%;\r\n    border-bottom: 12.41px solid #1e2530;\r\n  }\r\n  &::after {\r\n    top: 100%;\r\n    width: 0;\r\n    border-top: 12.41px solid #1e2530;\r\n  }\r\n  &:hover {\r\n    &::after {\r\n      border-bottom-color: $primary-color;\r\n    }\r\n    &::before {\r\n      border-top-color: $primary-color;\r\n    }\r\n  }\r\n}\r\n\r\n.contact-form {\r\n  .input-field {\r\n    margin-bottom: 10px;\r\n    &.name {\r\n      margin-right: 5px;\r\n    }\r\n    &.email {\r\n      margin-left: 5px;\r\n    }\r\n    label.error {\r\n      color: #ff0000;\r\n      font-size: 13px;\r\n      margin: 0;\r\n    }\r\n  }\r\n\r\n  .input-icon {\r\n    background-color: $light-dark;\r\n    border-radius: 3px 0 0 3px;\r\n    border-right: 1px solid rgba($light, 0.2);\r\n    line-height: 48px;\r\n    min-width: 53px;\r\n    text-align: center;\r\n    left: 0;\r\n    line-height: 48px;\r\n    min-width: 53px;\r\n    position: absolute;\r\n    top: 0;\r\n  }\r\n\r\n  .form-control {\r\n    background-color: $light-dark;\r\n    color: #bcbcbc;\r\n    border: 0 none;\r\n    border-radius: 3px;\r\n    height: 48px;\r\n    padding-left: 70px;\r\n    width: 100%;\r\n    font-family: $open-sans;\r\n    &:focus {\r\n      box-shadow: none;\r\n      color: #fff;\r\n    }\r\n  }\r\n\r\n  textarea.form-control {\r\n    border-radius: 3px;\r\n    height: 120px;\r\n    padding: 15px 10px 15px 70px;\r\n  }\r\n\r\n  .message {\r\n    .input-icon {\r\n      position: absolute;\r\n      left: 0;\r\n      top: 0;\r\n    }\r\n  }\r\n}\r\n\r\n.msg-success,\r\n.msg-failed {\r\n  display: none;\r\n  margin-top: 15px;\r\n}\r\n\r\n.msg-success {\r\n  color: $primary-color;\r\n}\r\n\r\n.pt-table.desktop-768 .pt-tablecell {\r\n  padding-bottom: 110px;\r\n  padding-top: 60px;\r\n  .page-nav {\r\n    bottom: 40px;\r\n  }\r\n}\r\n\r\n/* =================================== */\r\n/*  Color Switcher\r\n/* =================================== */\r\n.preview-wrapper {\r\n  background-color: #fff;\r\n  border: 1px solid #ddd;\r\n  border-right: 0;\r\n  color: #333;\r\n  height: 150px;\r\n  right: 0px;\r\n  position: fixed;\r\n  top: 100px;\r\n  width: 260px;\r\n  z-index: 1200;\r\n  -webkit-transition: all 0.4s ease-in-out 0s;\r\n  -moz-transition: all 0.4s ease-in-out 0s;\r\n  -o-transition: all 0.4s ease-in-out 0s;\r\n  transition: all 0.4s ease-in-out 0s;\r\n  transform: translateX(100%);\r\n}\r\n.preview-wrapper.extend {\r\n  -webkit-transform: translateX(0px);\r\n  -moz-transform: translateX(0px);\r\n  -ms-transform: translateX(0px);\r\n  -o-transform: translateX(0px);\r\n  transform: translateX(0px);\r\n}\r\n.switcher-head {\r\n  color: #333;\r\n  font-size: 18px;\r\n  font-weight: 600;\r\n  height: 46px;\r\n  line-height: 46px;\r\n  position: relative;\r\n}\r\n.switcher-head span {\r\n  border-bottom: 2px solid #eeeeee;\r\n  display: block;\r\n  margin: 0 20px;\r\n}\r\n.switcher-trigger {\r\n  background-color: #fff;\r\n  border: 1px solid #ddd;\r\n  border-right: 0;\r\n  cursor: pointer;\r\n  font-size: 20px;\r\n  height: 48px;\r\n  left: -48px;\r\n  line-height: 46px;\r\n  position: absolute;\r\n  text-align: center;\r\n  top: -1px;\r\n  width: 48px;\r\n}\r\n.switcher-body {\r\n  background-color: #fff;\r\n  height: -webkit-calc(100% - 50px);\r\n  height: calc(100% - 50px);\r\n  left: 0;\r\n  padding: 20px;\r\n  position: fixed;\r\n  right: 0;\r\n  top: 47px;\r\n  outline: none;\r\n}\r\n.switcher-body h4 {\r\n  font-size: 16px;\r\n  margin-bottom: 10px;\r\n}\r\n.switcher-body select {\r\n  border: 1px solid #e5e5e5;\r\n  height: 40px;\r\n  margin-bottom: 20px;\r\n  width: 100%;\r\n  -webklit--appearance: none;\r\n  -moz-appearance: none;\r\n  appearance: none;\r\n}\r\n.color-options {\r\n  margin-bottom: 10px;\r\n  padding: 0;\r\n}\r\n.color-options li {\r\n  display: inline-block;\r\n  background-color: #e6ae03;\r\n  height: 30px;\r\n  margin-bottom: 10px;\r\n  margin-right: 6px;\r\n  text-indent: -9999em;\r\n  width: 30px;\r\n  cursor: pointer;\r\n}\r\n.color-options li.c0 {\r\n  background-color: #fa6862;\r\n}\r\n.color-options li.c1 {\r\n  background-color: #02b7ce;\r\n}\r\n.color-options li.c2 {\r\n  background-color: #86a438;\r\n}\r\n.color-options li.c3 {\r\n  background-color: #f3a36d;\r\n}\r\n.pattern-options li {\r\n  font-family: \"Roboto\", sans-serif;\r\n  border: 1px solid #cccccc;\r\n  cursor: pointer;\r\n  float: left;\r\n  height: 40px;\r\n  margin: 0 10px 10px 0;\r\n  text-transform: capitalize;\r\n  width: 50px;\r\n}\r\n.pattern-options li:last-child {\r\n  border: 0 none;\r\n  height: auto;\r\n  padding-top: 8px;\r\n  width: auto;\r\n}\r\n.pattern-options li img {\r\n  width: 100%;\r\n  height: 100%;\r\n}\r\n\r\n/*------------------------------------------------\r\n\tResponsive Media Queries\r\n-------------------------------------------------*/\r\n@import \"media-queries\";\r\n@import \"dark\";\r\n","/*------------------------------------------------\r\n    Home Page\r\n-------------------------------------------------*/\r\n.page-home {\r\n  background-position: center center;\r\n  background-repeat: no-repeat;\r\n  background-size: cover;\r\n  vertical-align: middle;\r\n  .overlay {\r\n    background-color: rgba($light, 0.93);\r\n  }\r\n}\r\n\r\n/* End of container */\r\n\r\n// Contains 2 hexagons (.hex)\r\n.hexagon-item {\r\n  cursor: pointer;\r\n  width: $hexWidth;\r\n  height: $hexHeight;\r\n  float: left;\r\n  margin-left: -29px;\r\n  z-index: 0;\r\n  position: relative;\r\n  @include transform(rotate(30deg));\r\n  &:first-child {\r\n    margin-left: 0;\r\n  }\r\n  // Hover state\r\n  &:hover {\r\n    z-index: 1;\r\n    .hex-item:last-child {\r\n      opacity: 1;\r\n      @include transform(scale(1.3));\r\n    }\r\n    .hex-item:first-child {\r\n      opacity: 1;\r\n      @include transform(scale(1.2));\r\n      div:before,\r\n      div:after {\r\n        height: $borderHover;\r\n      }\r\n    }\r\n    .hex-item {\r\n      div::before,\r\n      div::after {\r\n        background-color: $primary-color;\r\n      }\r\n    }\r\n    .hex-content svg {\r\n      @include transform(scale(0.97));\r\n    }\r\n  }\r\n}\r\n\r\n// The menu wraps at four hexagons per row, so everything from the fifth\r\n// onwards is the second row and gets nudged into the first row's valleys.\r\n.page-home {\r\n  .hexagon-item:nth-child(n + 5) {\r\n    @include transform(rotate(30deg) translate(87px, -80px));\r\n  }\r\n}\r\n\r\n// Contains 3 div that makes the hexagon\r\n.hex-item {\r\n  position: absolute;\r\n  top: 0;\r\n  left: calc($edgeSize/2);\r\n  width: $edgeSize;\r\n  height: $hexHeight;\r\n  // Inset\r\n  &:first-child {\r\n    z-index: 0;\r\n    @include transform(scale(0.9));\r\n    @include transition(all 0.3s $ease-out-quart);\r\n  }\r\n  // Outset\r\n  &:last-child {\r\n    transition: all 0.3s $ease-out-expo;\r\n    z-index: 1;\r\n  }\r\n  div {\r\n    box-sizing: border-box;\r\n    position: absolute;\r\n    top: 0;\r\n    width: $edgeSize;\r\n    height: $hexHeight;\r\n    @include transform-origin(center center);\r\n    &::before,\r\n    &::after {\r\n      background-color: $light-dark;\r\n      content: \"\";\r\n      position: absolute;\r\n      width: 100%;\r\n      height: 3px;\r\n      @include transition(all 0.3s $ease-out-quart 0s);\r\n    }\r\n    &:before {\r\n      top: 0;\r\n    }\r\n    &:after {\r\n      bottom: 0;\r\n    }\r\n    &:nth-child(1) {\r\n      @include transform(rotate(0deg));\r\n    }\r\n    &:nth-child(2) {\r\n      @include transform(rotate(60deg));\r\n    }\r\n    &:nth-child(3) {\r\n      @include transform(rotate(120deg));\r\n    }\r\n  }\r\n}\r\n\r\n.hex-content {\r\n  color: $light;\r\n  display: block;\r\n  height: 180px;\r\n  margin: 0 auto;\r\n  position: relative;\r\n  text-align: center;\r\n  transform: rotate(-30deg);\r\n  width: 156px;\r\n  .hex-content-inner {\r\n    left: 50%;\r\n    margin: -3px 0 0 2px;\r\n    position: absolute;\r\n    top: 50%;\r\n    @include transform(translate(-50%, -50%));\r\n  }\r\n  .icon {\r\n    display: block;\r\n    font-size: 36px;\r\n    line-height: 30px;\r\n    margin-bottom: 11px;\r\n  }\r\n  .title {\r\n    display: block;\r\n    font-family: $open-sans;\r\n    font-size: 14px;\r\n    letter-spacing: 1px;\r\n    line-height: 24px;\r\n    text-transform: uppercase;\r\n  }\r\n  svg {\r\n    left: -7px;\r\n    position: absolute;\r\n    top: -13px;\r\n    transform: scale(0.87);\r\n    z-index: -1;\r\n    @include transition(all 0.3s $ease-out-quart 0s);\r\n  }\r\n  &:hover {\r\n    color: $light;\r\n  }\r\n}\r\n","\r\n/*------------------------------------------------\r\n    Welcome Page\r\n-------------------------------------------------*/\r\n\r\n.author-image-large {\r\n    position: absolute;\r\n    right: 0;\r\n    top: 0;\r\n    img {\r\n        @include calc(height, \"100vh - 4px\");\r\n    }\r\n}\r\n\r\n// .hexagon-item {\r\n// \ta {\r\n// \t\tpath {\r\n// \t\t\tfill: #59C4B4;\r\n// \t\t}\r\n// \t}\r\n// }","\r\n/*------------------------------------------------\r\n    About Page\r\n-------------------------------------------------*/\r\n.about-author {\r\n\tmargin-bottom: 23px;\r\n\t@include align-items(center);\r\n\t@include flexbox();\r\n\t.author-thumb {\r\n\t  \tbackground-color: $light;\r\n\t  \tborder: 5px solid $light-dark;\r\n\t  \tmargin-right: 30px;\r\n\t  \tpadding: 5px;\r\n\t  \timg {\r\n\t  \t\tborder: 2px solid $light-dark;\r\n\t  \t\twidth: 145px;\r\n\t  \t}\r\n\t}\r\n\t.author-desc {\r\n\t\tp {\r\n\t\t\tcolor: $light-dark;\r\n\t\t\tfont-family: $open-sans;\r\n\t\t\tletter-spacing: 1px;\r\n\t\t\tmargin-bottom: 4px;\r\n\t\t\ttext-transform: uppercase;\r\n\t\t}\r\n\t\tb {\r\n\t\t\tfont-family: $open-sans;\r\n\t\t}\r\n\t}\r\n}","/*------------------------------------------------\n    Games Page\n-------------------------------------------------*/\n.page-games {\n  .page-title {\n    margin-bottom: 22px;\n  }\n}\n\n// View switch (All / Daily)\n.games-view {\n  display: inline-block;\n  list-style: none;\n  margin: 0 0 12px;\n  padding: 0;\n  li {\n    display: inline-block;\n    margin: 0 12px;\n  }\n  a {\n    border-bottom: 2px solid transparent;\n    display: inline-block;\n    font-family: $open-sans;\n    font-size: 14px;\n    letter-spacing: 1px;\n    padding-bottom: 2px;\n    text-transform: uppercase;\n  }\n  .active {\n    border-bottom-color: $primary-color;\n    color: $primary-color;\n  }\n}\n\n.games-note {\n  font-family: $open-sans;\n  font-size: 12px;\n  letter-spacing: 1px;\n  margin-bottom: 30px;\n  min-height: 22px;\n  text-transform: uppercase;\n  b {\n    color: $title-color;\n    font-weight: 600;\n  }\n}\n\n.games-empty {\n  font-family: $open-sans;\n  font-size: 14px;\n  margin-bottom: 40px;\n}\n\n// Flex row so every card in a row is the same height whatever the tagline\n// length, and so a part-full last row stays centred.\n.games-grid {\n  @include flexbox();\n  @include flex-wrap(wrap);\n  @include justify-content(center);\n  // bootstrap's clearfix pseudo elements would become flex items here\n  &::before,\n  &::after {\n    display: none;\n  }\n  & > div {\n    margin-bottom: 30px;\n    @include flexbox();\n  }\n}\n\n// Game card\n.game-item {\n  background-color: $light-dark;\n  font-family: $open-sans;\n  padding: 28px 20px 26px;\n  position: relative;\n  text-align: center;\n  width: 100%;\n  @include flexbox();\n  @include flex-direction(column);\n  @include transition(all 0.3s ease 0s);\n\n  // decorative only - without this it sits over the play button and eats clicks\n  &::before {\n    border: 1px solid rgba($light, 0.08);\n    bottom: 12px;\n    content: \"\";\n    left: 12px;\n    pointer-events: none;\n    position: absolute;\n    right: 12px;\n    top: 12px;\n    @include transition(all 0.3s ease 0s);\n  }\n\n  h4 {\n    color: $primary-color;\n    font-size: 16px;\n    font-weight: 700;\n    letter-spacing: 0.96px;\n    margin-bottom: 12px;\n    text-transform: uppercase;\n  }\n\n  // grows to fill the tallest card in the row, keeping the badges and\n  // the button on a common baseline across the row\n  .game-tagline {\n    color: #aaaaaa;\n    font-size: 13px;\n    line-height: 22px;\n    margin-bottom: 15px;\n    @include flex-grow(1);\n  }\n\n  &:hover {\n    &::before {\n      bottom: 8px;\n      left: 8px;\n      right: 8px;\n      top: 8px;\n    }\n    .game-hex {\n      background-color: $primary-color;\n      &::before {\n        border-bottom-color: $primary-color;\n      }\n      &::after {\n        border-top-color: $primary-color;\n      }\n    }\n  }\n}\n\n// Hexagon icon holder, same construction as the contact/history hexes\n.game-hex {\n  background-color: #293342;\n  display: block;\n  height: 32.33px;\n  margin: 16.16px auto 24px;\n  position: relative;\n  width: 56px;\n  @include transition(all 0.3s ease 0s);\n  // left is explicit because the card centres its text, which would\n  // otherwise shift the static position of these two triangles.\n  &::before,\n  &::after {\n    border-left: 28px solid transparent;\n    border-right: 28px solid transparent;\n    content: \"\";\n    left: 0;\n    position: absolute;\n    width: 0;\n    @include transition(all 0.3s ease 0s);\n  }\n  &::before {\n    border-bottom: 16.16px solid #293342;\n    bottom: 100%;\n  }\n  &::after {\n    border-top: 16.16px solid #293342;\n    top: 100%;\n  }\n  i {\n    color: $light;\n    font-size: 24px;\n    left: 50%;\n    position: absolute;\n    top: 50%;\n    z-index: 1;\n    @include transform(translate(-50%, -50%));\n  }\n}\n\n// Fixed line-height so a card with no badges is exactly as tall as one with.\n.game-meta {\n  line-height: 20px;\n  min-height: 22px;\n}\n\n.game-badge {\n  border-radius: 2px;\n  color: #cfd6e4;\n  display: inline-block;\n  font-size: 10px;\n  letter-spacing: 1px;\n  line-height: 20px;\n  margin: 0 1px;\n  padding: 0 8px;\n  text-transform: uppercase;\n  vertical-align: top;\n  background-color: #293342;\n  &.daily {\n    background-color: $primary-color;\n    color: $light;\n  }\n  &.soon {\n    background-color: transparent;\n    border: 1px solid #3a465c;\n    color: #8b97ab;\n    line-height: 18px;\n  }\n  &.played {\n    background-color: transparent;\n    border: 1px solid #4a7f63;\n    color: #7fc6a1;\n    line-height: 18px;\n  }\n}\n\n.game-play {\n  border: 1px solid rgba($light, 0.25);\n  color: $light;\n  display: inline-block;\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: 1px;\n  line-height: 34px;\n  margin-top: 18px;\n  padding: 0 26px;\n  text-transform: uppercase;\n  @include align-self(center);\n  &:hover,\n  &:focus {\n    background-color: $primary-color;\n    border-color: $primary-color;\n    color: $light;\n  }\n  &.disabled {\n    border-style: dashed;\n    color: #8b97ab;\n    cursor: default;\n    pointer-events: none;\n  }\n}\n","/*============================================================\r\n\tMacbook pro 13 inch\r\n==============================================================*/\r\n@media only screen and (min-width: 1151px) and (max-width: 1366px) {}\r\n\r\n\r\n/*============================================================\r\n\tFor Small Desktop / tablet landscape\r\n==============================================================*/\r\n\r\n@media (min-width: 980px) and (max-width: 1150px) {\r\n\r\n\r\n\t.author-image-large {\r\n\t\timg {\r\n\t\t\t@include calc(height, \"80vh - 4px\");\r\n\t\t}\r\n\t}\r\n}\r\n\r\n\r\n/*============================================================\r\n\tTablet (Portrait) Design for a width of 768px\r\n==============================================================*/\r\n\r\n@media (min-width: 768px) and (max-width: 979px) {\r\n\tbody {\r\n\t\toverflow-x: hidden;\r\n\t}\r\n\r\n\t.page-title {\r\n\t\th2 {\r\n\t\t\tfont-size: 40px;\r\n\t\t}\r\n\r\n\t\t.title-bg {\r\n\t\t\tfont-size: 100px;\r\n\t\t}\r\n\t}\r\n\r\n\t.author-image-large {\r\n\t\tposition: static;\r\n\t\tmargin-bottom: 50px;\r\n\r\n\t\timg {\r\n\t\t\tdisplay: block;\r\n\t\t\theight: auto;\r\n\t\t\tmargin: 0 auto;\r\n\t\t\twidth: 50%;\r\n\t\t}\r\n\t}\r\n\r\n\t.about-author {\r\n\t\t+p {\r\n\t\t\tmargin-bottom: 50px;\r\n\t\t}\r\n\t}\r\n\r\n\t.service-hex {\r\n\t\twidth: 33.3333%;\r\n\r\n\t\t&:hover {\r\n\t\t\tz-index: 2;\r\n\r\n\t\t\tsvg {\r\n\t\t\t\t@include transform(scale(1.5));\r\n\t\t\t}\r\n\r\n\t\t\t.content {\r\n\t\t\t\twidth: 105%;\r\n\t\t\t}\r\n\t\t}\r\n\r\n\t\t&:nth-child(4),\r\n\t\t&:nth-child(5) {\r\n\t\t\t@include transform(translate(50%, -15%));\r\n\t\t}\r\n\t}\r\n\r\n\t.testimonials {\r\n\t\t.item {\r\n\t\t\tpadding-top: 45px;\r\n\t\t}\r\n\r\n\t\t.thumb {\r\n\t\t\tmargin-top: -45px;\r\n\t\t}\r\n\t}\r\n\r\n\t.history-item .history